/**
 * Passage 1: the palette, a toned panel, and a lean rub-in of the darks.
 *
 * Seven tubes go on the palette, and every pile the painting uses is mixed from them
 * here, at fixed parts, before a brush touches the panel. Where a color has to shift
 * across the picture (the sky from the grey overhead to the glow, the woods from shadow
 * into the light, the elms from their dark core up into the fog), it is mixed as a few
 * separate steps, and later passages lay the steps side by side. A thin warm wash tones
 * the panel, and the few dark shapes (the elms on the spit, their reflection, the mud
 * bar) are rubbed in with lean umber so the design is fixed before any body color goes on.
 */

// The tubes. Every other color in the painting is mixed from these.
palette('white', '#f2eee3');
palette('ochre', '#c09a4e');
palette('umber', '#5f4f3a');
palette('sienna', '#8c4f2e');
palette('ultra', '#2b3a8a');
palette('terre', '#6f7d5e');
palette('rose', '#a85a68');

// The sky in six steps, from the glow where the sun is behind the fog to the grey overhead.
palette('sky0', mix(['white', 12], ['ochre', 1], ['rose', 0.12]));
palette('sky1', mix(['white', 10], ['ochre', 1], ['rose', 0.18], ['umber', 0.15]));
palette('sky2', mix(['white', 8], ['ochre', 0.8], ['rose', 0.2], ['umber', 0.35], ['ultra', 0.06]));
palette('sky3', mix(['white', 7], ['ochre', 0.6], ['rose', 0.2], ['umber', 0.55], ['ultra', 0.14]));
palette(
  'sky4',
  mix(['white', 6], ['ochre', 0.45], ['rose', 0.18], ['umber', 0.7], ['ultra', 0.24]),
);
palette(
  'sky5',
  mix(['white', 5], ['ochre', 0.35], ['rose', 0.15], ['umber', 0.8], ['ultra', 0.34]),
);
// The fog itself: white warmed a breath.
palette('fog', mix(['white', 14], ['ochre', 0.6], ['rose', 0.2], ['ultra', 0.12]));

// The pond: the tint still water lays over whatever it mirrors, a little darker and greener.
palette('pond', mix(['terre', 1], ['umber', 0.6], ['white', 1.5], ['ultra', 0.15]));
// The water mirrors the sky step for step, the near water greener than the far.
palette('pool3', mix(['sky3', 5], ['pond', 0.8]));
palette('pool4', mix(['sky4', 5], ['pond', 1.2]));
palette('pool5', mix(['sky5', 5], ['pond', 1.6]));
palette('poolNear', mix(['sky5', 5], ['pond', 2.1]));
// The glow's reflection keeps more of its light.
palette('glint3', mix(['sky3', 5], ['pond', 0.55]));
palette('glint2', mix(['sky2', 5], ['pond', 0.4]));
palette('glint1', mix(['sky1', 5], ['pond', 0.3]));
palette('glint0', mix(['sky0', 5], ['pond', 0.2]));

// The woods across the pond, two planes, each in three steps from shade into the light.
palette('farther', mix(['sky4', 5], ['terre', 0.5], ['ultra', 0.1]));
palette('fartherHalf', mix(['farther', 2], ['sky2', 0.6]));
palette('fartherLit', mix(['farther', 2], ['sky2', 1.3]));
palette('farWood', mix(['sky5', 3], ['terre', 1], ['umber', 0.3], ['ultra', 0.15]));
palette('farWoodHalf', mix(['farWood', 2], ['sky2', 1.1]));
palette('farWoodLit', mix(['farWood', 2], ['sky2', 2.3]));
// Their reflections, in three steps as the fog on the water takes them.
palette('woodMirror', mix(['farWood', 2], ['pond', 0.6], ['sky2', 0.9]));
palette('woodMirrorPale', mix(['farWood', 2], ['pond', 0.6], ['sky2', 1.8]));
palette('woodMirrorLost', mix(['farWood', 2], ['pond', 0.6], ['sky2', 2.8]));
// The bank of fog lying on the water, grey in the shade and warm under the glow.
palette('mist', mix(['sky3', 2], ['fog', 1]));
palette('mistHalf', mix(['sky3', 2], ['fog', 1], ['sky1', 1]));
palette('mistLit', mix(['sky3', 2], ['fog', 1], ['sky1', 2]));

// The elms: green-grey foliage, a deeper core, bark; then the steps they take into the fog,
// from the dark of the lower crown to the tops, where the fog has nearly taken them.
palette('elm', mix(['terre', 2], ['umber', 1.3], ['white', 1.6], ['ultra', 0.25], ['rose', 0.1]));
palette('elmDeep', mix(['terre', 1.5], ['umber', 1.6], ['white', 0.8], ['ultra', 0.35]));
palette('bark', mix(['umber', 2], ['ultra', 0.5], ['terre', 0.6], ['white', 0.7]));
palette('crownCore', mix(['elmDeep', 2], ['fog', 0.12]));
palette('crown', mix(['elmDeep', 2], ['fog', 0.5]));
palette('crownMid', mix(['elm', 2], ['fog', 0.45]));
palette('crownHaze', mix(['elm', 2], ['fog', 1.2]));
palette('crownFog', mix(['elm', 2], ['fog', 2.6]));
palette('crownLost', mix(['elm', 1], ['fog', 3], ['sky4', 2]));
palette('trunk', mix(['bark', 2], ['fog', 0.2]));
palette('limb', mix(['bark', 2], ['fog', 0.45]));
// Their reflection: the crown dulled by the pond and taken by the fog in four steps.
palette('elmMirrorDeep', mix(['crownCore', 2], ['pond', 0.8], ['sky4', 1]));
palette('elmMirror', mix(['crown', 2], ['pond', 0.8], ['sky4', 1.6]));
palette('elmMirrorPale', mix(['crown', 2], ['pond', 0.8], ['sky4', 3]));
palette('elmMirrorLost', mix(['crown', 1], ['pond', 0.6], ['sky4', 3.6]));
palette('trunkMirror', mix(['bark', 2], ['pond', 0.8], ['sky4', 1.6]));
// The level lines of the water's skin that break a reflection.
palette('skin', mix(['sky3', 3], ['pond', 1]));

// The banks: the spit under the elms, greyer toward its point, and the nearer mud bar.
palette('bank', mix(['umber', 2], ['terre', 1], ['sienna', 0.3], ['white', 1.1]));
palette('spit', mix(['bank', 2], ['fog', 2.2]));
palette('spitPale', mix(['bank', 2], ['fog', 2.9]));
palette('spitPoint', mix(['bank', 2], ['fog', 3.7]));
palette('spitMirror', mix(['bank', 2], ['pond', 1], ['fog', 3.2]));
palette('grass', mix(['bank', 2], ['fog', 2.2]));
palette('grassPale', mix(['bank', 2], ['fog', 3.4]));
palette('bar', mix(['bank', 2], ['fog', 1.7]));
palette('barTip', mix(['bank', 2], ['fog', 2.5]));
palette('barLip', mix(['bank', 2], ['umber', 0.5], ['fog', 0.6]));
palette('barMirror', mix(['bank', 2], ['pond', 1], ['fog', 2.2]));
palette('rush', mix(['bank', 2], ['ochre', 0.1], ['fog', 1.1]));
palette('rushPale', mix(['bank', 2], ['ochre', 0.1], ['fog', 1.7]));
palette('rushLost', mix(['bank', 2], ['ochre', 0.1], ['fog', 2.3]));
palette('windLine', mix(['sky1', 3], ['pond', 0.6]));

// The two hard notes: the heron and the silver of the wind-lane.
palette('heron', mix(['umber', 2], ['ultra', 1], ['white', 0.7]));
palette('heronLit', mix(['heron', 1], ['sky1', 2]));
palette('heronMirror', mix(['heron', 1], ['pond', 0.6], ['sky2', 0.8]));
palette('heronMirrorPale', mix(['heron', 1], ['pond', 0.8], ['sky2', 1.2]));
palette('silver', mix(['white', 10], ['ochre', 0.5]));
palette('ripple', mix(['silver', 1], ['sky2', 3]));

const W = canvas.width;
const H = canvas.height;
const SPIT = 660; // the waterline under the elms

/** The elms on the spit, as passage 4 paints them: foot, crown top, lean, and half-spread. */
const ELMS = [
  { x: 66, top: 150, lean: -18, spread: 112 },
  { x: 172, top: 58, lean: 8, spread: 142 },
  { x: 318, top: 128, lean: 20, spread: 106 },
  { x: 482, top: 262, lean: 12, spread: 80 },
];

brush('wash', { type: 'soft', width: 220, reservoir: 6 });
brush('rub', { type: 'soft', width: 70, reservoir: 2 });

// The toning: a thin warm film over the whole panel in big crossing sweeps.
palette('toning', mix(['ochre', 1], ['white', 3], ['sienna', 0.3], ['umber', 0.2]));
for (let pass = 0; pass < 2; pass++) {
  const tilt = pass === 0 ? 0.18 : -0.14;
  for (let y = -120; y < H + 120; y += 150) {
    stroke({
      path: [
        [-60, y + rand(-20, 20)],
        [W / 2, y + (W / 2) * tilt + rand(-30, 30)],
        [W + 60, y + W * tilt + rand(-20, 20)],
      ],
      brush: 'wash',
      color: 'toning',
      paint: 'semi_opaque',
      thinner: 0.75,
      load: rand(0.55, 0.75),
    });
  }
}
dry();

// The rub-in: lean umber where the darks will stand.
palette('rubIn', mix(['umber', 2], ['terre', 1], ['white', 2]));
const rubIn = { color: 'rubIn', thinner: 0.7, load: 0.6, paint: 'semi_opaque' };
for (const e of ELMS) {
  // the crown as a few loose sweeps, broadest across the shoulders and narrower over the
  // arch underneath; the trunk and its fork as a short line
  const foot = SPIT - 25;
  const h = foot - e.top;
  for (let v = 0.12; v < 0.72; v += 0.1) {
    const half = e.spread * (v < 0.4 ? 0.75 + 0.6 * v : 0.99 - 0.9 * (v - 0.4));
    const y = e.top + v * h;
    stroke({
      path: [
        [e.x + e.lean - half, y + rand(-8, 8)],
        [e.x + e.lean + half, y + rand(-8, 8)],
      ],
      brush: 'rub',
      ...rubIn,
    });
  }
  stroke({
    path: [
      [e.x, foot],
      [e.x + e.lean * 0.3, foot - 0.35 * h],
    ],
    brush: { type: 'soft', width: 18 },
    ...rubIn,
  });
}
// the spit, the elms' reflection hanging below it to the bottom edge, and the mud bar
for (let y = SPIT - 30; y < H; y += 40)
  stroke({
    path: [
      [-40, y],
      [280, y + rand(-6, 6)],
      [570 - Math.max(0, 70 - (y - SPIT)), y],
    ],
    brush: 'rub',
    ...rubIn,
    load: y < SPIT + 120 ? 0.45 : 0.4,
  });
stroke({
  path: [
    [760, 796],
    [1100, 788],
    [W + 40, 780],
  ],
  brush: { type: 'soft', width: 24 },
  ...rubIn,
});

dry();

/**
 * Passage 2: the sky and the still water, wet and blended.
 *
 * Fog light has no edges, so nothing here may show where a stroke began. The sky goes
 * on in broad level rows of thinned paint that run off both sides of the panel, from the
 * grey overhead down to the warmer grey at the waterline: each row takes the sky step of
 * its band, and where two bands meet, a row takes one step or the other at random, so the
 * steps knit together while wet. While the rows are wet, the glow is laid into them as
 * nested strokes centered under the sun, each a step lighter than the last and tapering
 * at both ends, so they melt into the rows they cross. The water is the same sky turned
 * over, in the pond's steps. Both stay wet, so the far woods can be painted into them.
 */

const W = canvas.width;
const H = canvas.height;
const WATER = 525; // the far waterline
const GLOW = { x: 1040, y: 300 };

/** The glow's rings: radius (px, before the 1.6× horizontal stretch) and the steps in sky and water. */
const RINGS = [
  { r: 330, sky: 'sky3', water: 'glint3' },
  { r: 240, sky: 'sky2', water: 'glint2' },
  { r: 160, sky: 'sky1', water: 'glint1' },
  { r: 90, sky: 'sky0', water: 'glint0' },
];

brush('broad', { type: 'soft', width: 190, reservoir: 6 });
brush('glow', { type: 'soft', width: 100, reservoir: 5 });

/** The sky step for a point at height y; the bands' borders wander by a row either way. */
function skyStep(y) {
  const j = y + rand(-45, 45);
  return j < 170 ? 'sky5' : j < 350 ? 'sky4' : 'sky3';
}
/** The water step for a row at height y: the step of the sky it mirrors, greener up close. */
function waterStep(y) {
  const j = 2 * WATER - y + rand(-45, 45);
  if (j < 170) return y + rand(-40, 40) > 880 ? 'poolNear' : 'pool5';
  return j < 350 ? 'pool4' : 'pool3';
}

/** One broad level row across the whole panel and off both sides. */
function row(y, color) {
  stroke({
    path: [
      [-80, y + rand(-4, 4)],
      [W * 0.35, y + rand(-4, 4)],
      [W * 0.7, y + rand(-4, 4)],
      [W + 80, y + rand(-4, 4)],
    ],
    brush: 'broad',
    color,
    load: rand(0.55, 0.65),
    thinner: 0.45,
  });
}

/** The glow's nested strokes at height y, for a glow centered at height cy. */
function glowRow(y, cy, side) {
  for (const ring of RINGS) {
    const dy = y - cy + rand(-12, 12);
    const r = ring.r * rand(0.9, 1.1);
    if (Math.abs(dy) >= r) continue;
    const half = Math.sqrt(r * r - dy * dy) * 1.6;
    const cx = GLOW.x + rand(-25, 25);
    stroke({
      path: [
        [cx - half - 50, y + rand(-2, 2), 0.05],
        [cx - half * 0.4, y + rand(-2, 2), 0.7],
        [cx + half * 0.4, y + rand(-2, 2), 0.7],
        [cx + half + 50, y + rand(-2, 2), 0.05],
      ],
      brush: 'glow',
      color: ring[side],
      load: rand(0.55, 0.65),
      thinner: 0.4,
    });
  }
}

// The sky, top to bottom, then the glow into it.
for (let y = -40; y < WATER + 20; y += 38) row(y, skyStep(y));
for (let y = GLOW.y - 330; y < WATER; y += 28) glowRow(y, GLOW.y, 'sky');

// The water, from the far shore toward us, then the glow's reflection into it.
for (let y = WATER - 6; y < H + 90; y += 38) row(y, waterStep(y));
for (let y = WATER + 6; y < 2 * WATER - GLOW.y + 330; y += 28)
  glowRow(y, 2 * WATER - GLOW.y, 'water');

/**
 * Passage 3: the woods across the pond, and every reflection, painted into the wet paint.
 *
 * Two planes of trees: a ghost of higher ground far off on the right, and the long wood
 * on the far bank, which rises to a shoulder left of center and sinks into the light
 * under the glow. Each is filled with level strokes and topped with small arcs for the
 * crowns, all laid into the wet sky so every stroke picks up some fog and loses its
 * edge; under the glow the strokes change to the paler steps of the same green, their
 * border wandering so the steps knit. The water is still wet, so the reflections go in
 * now, as a painter puts them in with the water: the far wood hanging a little way down,
 * and on the left the dark mirror of the elms and their spit, which the next passage
 * stands up above them. Each is laid in level strokes that pale step by step as they go
 * down, until the fog lying on the water takes them, and a few level lines of the
 * water's skin break them. Last, a bank of mist along the far waterline, so the woods
 * float on it. Everything stays wet for the elms.
 */

const W = canvas.width;
const WATER = 525;
const SPIT = 660; // the waterline under the elms
const GLOW = { x: 1040, y: 300 };

/** The long wood's skyline: a shoulder left of center, sinking toward the light. */
function farTop(x) {
  const shoulder = 72 * Math.exp(-(((x - 470) / 330) ** 2));
  const sink = Math.max(0, x - 900) * 0.055;
  return WATER - 46 - shoulder + sink - 18 * noise(x / 80, 1.7) - 9 * noise(x / 24, 3.9);
}
/** The far hills' skyline, behind the wood on the right. */
function fartherTop(x) {
  return WATER - 72 - 58 * Math.exp(-(((x - 1290) / 230) ** 2)) - 16 * noise(x / 140, 8.2);
}
/** Which light a point of the woods stands in: 2 under the glow, 1 at its edge, 0 in the shade. */
function lightAt(x, y) {
  const d = (x + 90 * noise(x / 70, y / 45) - GLOW.x) / 260;
  const g = Math.exp(-d * d);
  return g > 0.55 ? 2 : g > 0.2 ? 1 : 0;
}

/**
 * The elms as passage 4 paints them: the trees, the spit's top, each crown's lobes, and
 * what step of the foliage a point of a crown takes. The reflection below mirrors these.
 */
const ELMS = [
  { x: 66, top: 150, lean: -18, spread: 112, far: 0 },
  { x: 172, top: 58, lean: 8, spread: 142, far: 0.3 },
  { x: 318, top: 128, lean: 20, spread: 106, far: 1 },
  { x: 482, top: 262, lean: 12, spread: 80, far: 1.8 },
];
const spitTop = (x) => SPIT - 34 * Math.max(0, 1 - x / 600) ** 0.7 - 3 * noise(x / 40, 6.1);
const LOBES = [
  [-0.62, 0.14, 0.4, 0.12],
  [-0.3, 0.09, 0.4, 0.11],
  [0, 0.08, 0.38, 0.09],
  [0.3, 0.09, 0.4, 0.11],
  [0.62, 0.14, 0.4, 0.12],
  [-0.9, 0.4, 0.28, 0.2],
  [0.9, 0.4, 0.28, 0.2],
  [0, 0.37, 0.8, 0.26],
  [-0.6, 0.63, 0.5, 0.11],
  [0.6, 0.63, 0.5, 0.11],
  [0, 0.56, 0.45, 0.08],
];
const TREES = ELMS.map((e, k) => {
  const foot = spitTop(e.x) + 4;
  const h = foot - e.top;
  const cx = e.x + e.lean;
  const lobes = LOBES.map(([u, v, ru, rv], j) => ({
    x: cx + (u + 0.12 * noise(k * 7.3 + j, 1.9)) * e.spread,
    y: e.top + (v + 0.04 * noise(k * 5.1 + j, 4.4)) * h,
    rx: ru * e.spread * (1 + 0.15 * noise(k * 3.7 + j, 7.7)),
    ry: rv * h * (1 + 0.15 * noise(k * 2.9 + j, 2.3)),
  }));
  return { ...e, k, foot, h, cx, fork: { x: e.x + e.lean * 0.3, y: foot - 0.1 * h }, lobes };
});
function depthIn(t, x, y) {
  let d = Number.NEGATIVE_INFINITY;
  let side = 0;
  for (const l of t.lobes) {
    const dx = x - l.x;
    const dy = y - l.y;
    const q = Math.hypot(dx / l.rx, dy / l.ry);
    const r = Math.hypot(dx, dy);
    const dl = q < 1e-6 ? Math.min(l.rx, l.ry) : r * (1 / q - 1);
    if (dl > d) {
      d = dl;
      side = Math.max(-1, Math.min(1, dy / l.ry));
    }
  }
  return {
    d: d + 8 * noise(x / 34 + t.k * 13, y / 34) + 3 * noise(x / 11, y / 11 + t.k * 5),
    side,
  };
}
function crownAt(x, y) {
  let depth = Number.NEGATIVE_INFINITY;
  let step = 9;
  for (const t of TREES) {
    const { d, side } = depthIn(t, x, y);
    depth = Math.max(depth, d);
    if (d <= 0) continue;
    const v = (y - t.top) / t.h;
    const value =
      t.far +
      Math.min(3, Math.max(0, (310 - y) / 85)) +
      (d < 6 ? 1.2 : d < 14 ? 0.5 : 0) -
      0.7 * side -
      (v > 0.45 && d > 12 ? 0.6 : 0) +
      0.5 * noise(x / 45, y / 45);
    step = Math.min(step, value);
  }
  return { depth, step: Math.min(5, Math.max(0, Math.round(step))) };
}

brush('mass', { type: 'soft', width: 30, reservoir: 3 });
brush('crown', { type: 'soft', width: 26 });
brush('veil', { type: 'soft', width: 44, reservoir: 5 });
brush('mirror', { type: 'soft', width: 14, reservoir: 3 });

/**
 * Fill a plane of trees from its skyline down to the fog, densest under the crowns and
 * thinning toward the water, then round the crowns with small arcs. `steps` are the
 * plane's piles from the shade into the light.
 */
function wood(top, steps) {
  for (let y = WATER + 4; y > 0; y -= 9) {
    for (let x = -40; x < W; x += rand(70, 120)) {
      const len = rand(90, 150);
      const cx = x + len / 2;
      const below = y - top(cx);
      if (below < 16) continue;
      stroke({
        path: [
          [x, y + rand(-2, 2)],
          [x + len, y + rand(-2, 2)],
        ],
        brush: 'mass',
        color: steps[lightAt(cx, y)],
        load: Math.max(0.4, 0.85 - below / 140) * rand(0.9, 1),
        thinner: 0.2,
      });
    }
  }
  for (let x = -20; x < W + 20; x += rand(10, 18)) {
    const r = rand(12, 26);
    const cy = top(x) + r * 0.8;
    const arc = [];
    for (let a = Math.PI + 0.3; a <= 2 * Math.PI - 0.3; a += 0.35)
      arc.push([x + Math.cos(a) * r * 0.9, cy + Math.sin(a) * r * 0.8]);
    stroke({
      path: arc,
      brush: 'crown',
      color: steps[lightAt(x, cy)],
      load: rand(0.65, 0.8),
      pressure: 0.65,
      thinner: 0.15,
    });
  }
}

wood(fartherTop, ['farther', 'fartherHalf', 'fartherLit']);
wood(farTop, ['farWood', 'farWoodHalf', 'farWoodLit']);

/**
 * The far wood's reflection: it hangs upside down in the water, as deep as it stands, but
 * the fog on the water swallows it within a few strokes. Laid in level rows, each
 * crossing only where the wood reaches that far down, a step paler every few rows.
 */
const MIRROR_STEPS = ['woodMirror', 'woodMirrorPale', 'woodMirrorLost'];
const depthAt = (x) => (WATER - farTop(x)) * 0.8;
for (let y = WATER + 4; y < WATER + 130; y += 8) {
  const d = y - WATER;
  let x = -40;
  while (x < W + 40) {
    if (depthAt(x) < d + rand(0, 12)) {
      x += 10;
      continue;
    }
    let x1 = x;
    while (x1 < W + 40 && depthAt(x1) > d) x1 += 10;
    const mid = (x + x1) / 2;
    const step = Math.floor((3 * (d + rand(-8, 8))) / depthAt(mid)) + (lightAt(mid, y) > 0 ? 1 : 0);
    stroke({
      path: [
        [x - 6, y + rand(-1, 1), 0.2],
        [mid, y + rand(-1.5, 1.5), 0.7],
        [x1 + 6, y + rand(-1, 1), 0.2],
      ],
      brush: { type: 'soft', width: 18 },
      color: MIRROR_STEPS[Math.min(2, Math.max(0, step))],
      load: rand(0.55, 0.7),
    });
    x = x1 + rand(10, 40);
  }
}

/**
 * The spit's bank turned over: a band as deep as the bank is high, narrowing to the
 * point. Then the elms' reflection, as deep below the waterline as each part stands above
 * it: the trunks and their limbs hanging down, and below them the dark of the lower
 * crowns, one mass where they overlap, darker than the water and paler than the trees.
 * It is laid in level strokes of staggered length, so no edge lines up from row to row,
 * and the fog lying on the water takes it step by step as it goes down.
 */
for (let y = SPIT + 3; y < SPIT + 36; y += 5) {
  let x1 = 0;
  while (x1 < 620 && SPIT - spitTop(x1) > y - SPIT) x1 += 6;
  if (x1 < 20) continue;
  stroke({
    path: [
      [-40, y + rand(-1, 1), 0.7],
      [x1 / 2, y + rand(-1, 1), 0.7],
      [x1 + rand(-6, 6), y + rand(-1, 1), 0.2],
    ],
    brush: 'mirror',
    color: 'spitMirror',
    load: rand(0.6, 0.7),
  });
}
// the trunks and limbs upside down, wavering a little, the limbs lost before the crowns
const mirror = ([x, y, p]) => [x + rand(-1.5, 1.5), 2 * SPIT - y, p];
for (const t of TREES) {
  const size = t.h / 570;
  const { fork } = t;
  const bole = [
    [t.x, t.foot + 2, 0.95],
    [t.x + t.lean * 0.12, t.foot - 0.05 * t.h, 0.9],
    [fork.x, fork.y, 0.8],
  ];
  // a broad pale stroke, then the trunk's own dark down the middle of it
  for (const [w, color, load] of [
    [30, 'elmMirror', 0.6],
    [15, 'trunkMirror', 0.65],
  ])
    stroke({ path: bole.map(mirror), brush: { type: 'soft', width: w * size }, color, load });
  const rise = fork.y - (t.top + 0.62 * t.h);
  for (const u of [-0.45, 0.04, 0.48]) {
    const dx = t.cx - fork.x + (u + 0.12 * noise(t.k * 4.1, u * 3)) * t.spread;
    const lift = rise * (1 + 0.15 * noise(t.k * 2.3, u * 5));
    stroke({
      path: [
        [fork.x + u * 8 * size, fork.y + 4, 0.8],
        [fork.x + dx * 0.18, fork.y - lift * 0.4, 0.65],
        [fork.x + dx * 0.45, fork.y - lift * 0.7, 0.4],
      ].map(mirror),
      brush: { type: 'soft', width: 14 * size },
      color: 'elmMirrorPale',
      load: 0.5,
    });
  }
}
// the crowns, a row every few px, each row crossing whatever crowns hang that far down
const ELM_STEPS = ['elmMirrorDeep', 'elmMirror', 'elmMirrorPale', 'elmMirrorLost'];
const crownFoot = Math.max(...TREES.map((t) => Math.max(...t.lobes.map((l) => l.y + l.ry))));
for (let y = 2 * SPIT - crownFoot - 6; y < canvas.height + 10; y += rand(6, 9)) {
  const ty = 2 * SPIT - y;
  const spans = [];
  for (let x = -30; x < 600; x += 5) {
    if (crownAt(x, ty).depth <= 0) continue;
    const last = spans.at(-1);
    if (last && x - last.x1 <= 5) last.x1 = x;
    else spans.push({ x0: x, x1: x });
  }
  const fade = 0.4 + Math.max(0, (y - SPIT - 150) / 70);
  for (const s of spans) {
    if (s.x1 - s.x0 < 12) continue;
    for (let x = s.x0 - rand(4, 18); x < s.x1 - 8; x += rand(35, 75)) {
      const x1 = Math.min(x + rand(50, 130), s.x1 + rand(-6, 16));
      if (x1 < x + 18) continue;
      const mid = (x + x1) / 2;
      const c = crownAt(mid, ty);
      const step = [0, 0, 1, 1, 2, 3][c.step] + fade + 0.5 * noise(mid / 50, y / 30);
      stroke({
        path: [
          [x, y + rand(-1, 1), 0.15],
          [mid, y + rand(-1.5, 1.5), 0.7],
          [x1, y + rand(-1, 1), 0.15],
        ],
        brush: { type: 'soft', width: rand(22, 30), reservoir: 2 },
        color: ELM_STEPS[Math.min(3, Math.max(0, Math.round(step)))],
        load: rand(0.55, 0.65),
      });
    }
  }
}
// the water's skin breaks the reflections level: a few faint lines of the pond across them
for (let y = SPIT + 24; y < canvas.height; y += rand(26, 44)) {
  for (let x = -40; x < 580; x += rand(160, 300)) {
    const len = rand(70, 170);
    stroke({
      path: [
        [x, y, 0.1],
        [x + len / 2, y + rand(-1, 1), 0.6],
        [x + len, y, 0.1],
      ],
      brush: { type: 'soft', width: 5 },
      color: 'skin',
      load: rand(0.55, 0.7),
    });
  }
}

// The bank of mist lying on the water along the far shore: the woods stand on nothing.
// Its steps match the sky low down, so it hides the wood's foot without a stripe.
const MIST_STEPS = ['mist', 'mistHalf', 'mistLit'];
for (let y = WATER - 34; y < WATER + 26; y += 6) {
  const thick = 1 - Math.abs(y - (WATER - 4)) / 32;
  for (let x = -60; x < W; x += rand(80, 150)) {
    const len = rand(180, 320);
    stroke({
      path: [
        [x, y + rand(-3, 3), 0.1],
        [x + len / 2, y + rand(-3, 3), 0.8],
        [x + len, y + rand(-3, 3), 0.1],
      ],
      brush: 'veil',
      color: MIST_STEPS[lightAt(x + len / 2, y)],
      load: (0.35 + thick * 0.45) * rand(0.9, 1.05),
      thinner: 0.35,
    });
  }
}

/**
 * Passage 4: the elms on the spit, standing dark in the fog.
 *
 * A low spit of land runs in from the left, and four elms stand on it, the heaviest dark
 * in the picture and still only a few steps darker than the fog. They are painted as a
 * tonalist paints trees in mist: one soft mass for the group, each crown legible by its
 * own dome against the fog, the nearer trees darker and the farther a step or two paler.
 * Each is an American elm: a short stout trunk forks low into a few limbs that rise in a
 * vase and vanish into the arched underside of a broad crown, whose sides droop.
 *
 * The sky and water are still wet, so the trees go into wet fog. The trunks and limbs go
 * in first; then each crown is built up in three layers of soft, thinned strokes laid
 * every which way but kept inside its silhouette: a lay-in over the whole crown, the body
 * inset from the edge, and the dark of the lower crown. Each layer picks up the elm paint
 * under it rather than fog, so the inside reaches its full value while the edge, touched
 * only by the lay-in, stays soft. Each lobe of foliage is darker underneath, and the
 * value rises with height, so the tops pale into the fog. Last, fog is drawn in across
 * the tops from the sky side, so it takes their edges without dragging them out.
 */

const SPIT = 660; // the waterline under the elms

/** The elms: foot, crown top, lean of the crown over the foot, half-spread, and how far (in fog steps). */
const ELMS = [
  { x: 66, top: 150, lean: -18, spread: 112, far: 0 },
  { x: 172, top: 58, lean: 8, spread: 142, far: 0.3 },
  { x: 318, top: 128, lean: 20, spread: 106, far: 1 },
  { x: 482, top: 262, lean: 12, spread: 80, far: 1.8 },
];

/** The top of the spit's grass at x: a low bank tapering out to a point. */
const spitTop = (x) => SPIT - 34 * Math.max(0, 1 - x / 600) ** 0.7 - 3 * noise(x / 40, 6.1);

/**
 * An elm crown as overlapping lobes, in units of its spread across and its height down
 * from the top: the dome, the drooping shoulders, the body, and the clumps hanging under it.
 */
const LOBES = [
  [-0.62, 0.14, 0.4, 0.12],
  [-0.3, 0.09, 0.4, 0.11],
  [0, 0.08, 0.38, 0.09],
  [0.3, 0.09, 0.4, 0.11],
  [0.62, 0.14, 0.4, 0.12],
  [-0.9, 0.4, 0.28, 0.2],
  [0.9, 0.4, 0.28, 0.2],
  [0, 0.37, 0.8, 0.26],
  [-0.6, 0.63, 0.5, 0.11],
  [0.6, 0.63, 0.5, 0.11],
  [0, 0.56, 0.45, 0.08],
];

/** Each elm's foot, height, fork, and lobes in px, varied by the noise field so no two repeat. */
const TREES = ELMS.map((e, k) => {
  const foot = spitTop(e.x) + 4;
  const h = foot - e.top;
  const cx = e.x + e.lean;
  const lobes = LOBES.map(([u, v, ru, rv], j) => ({
    x: cx + (u + 0.12 * noise(k * 7.3 + j, 1.9)) * e.spread,
    y: e.top + (v + 0.04 * noise(k * 5.1 + j, 4.4)) * h,
    rx: ru * e.spread * (1 + 0.15 * noise(k * 3.7 + j, 7.7)),
    ry: rv * h * (1 + 0.15 * noise(k * 2.9 + j, 2.3)),
  }));
  return { ...e, k, foot, h, cx, fork: { x: e.x + e.lean * 0.3, y: foot - 0.1 * h }, lobes };
});

/**
 * How far (px) a point lies inside tree t's crown (negative outside), and where it sits
 * in the lobe it is deepest in, from -1 at that lobe's top to 1 at its underside. The rim
 * wanders with the noise.
 */
function depthIn(t, x, y) {
  let d = Number.NEGATIVE_INFINITY;
  let side = 0;
  for (const l of t.lobes) {
    const dx = x - l.x;
    const dy = y - l.y;
    const q = Math.hypot(dx / l.rx, dy / l.ry);
    const r = Math.hypot(dx, dy);
    const dl = q < 1e-6 ? Math.min(l.rx, l.ry) : r * (1 / q - 1);
    if (dl > d) {
      d = dl;
      side = Math.max(-1, Math.min(1, dy / l.ry));
    }
  }
  return {
    d: d + 8 * noise(x / 34 + t.k * 13, y / 34) + 3 * noise(x / 11, y / 11 + t.k * 5),
    side,
  };
}

/** The foliage piles from the dark of the lower crown up into the fog. */
const LADDER = ['crownCore', 'crown', 'crownMid', 'crownHaze', 'crownFog', 'crownLost'];

/**
 * The crown at a point: how deep inside it is, and which step of the ladder it takes.
 * Where crowns overlap, the darker (nearer) one is seen. Fog thickens with height and
 * takes the rim; each lobe is darker on its underside, and the lower crown, in its own
 * shadow, darkest of all.
 */
function crownAt(x, y) {
  let depth = Number.NEGATIVE_INFINITY;
  let step = 9;
  for (const t of TREES) {
    const { d, side } = depthIn(t, x, y);
    depth = Math.max(depth, d);
    if (d <= 0) continue;
    const v = (y - t.top) / t.h;
    const value =
      t.far +
      Math.min(3, Math.max(0, (310 - y) / 85)) +
      (d < 6 ? 1.2 : d < 14 ? 0.5 : 0) -
      0.7 * side -
      (v > 0.45 && d > 12 ? 0.6 : 0) +
      0.5 * noise(x / 45, y / 45);
    step = Math.min(step, value);
  }
  return { depth, step: Math.min(5, Math.max(0, Math.round(step))) };
}

// The spit: level strokes of bank, greyer toward its point, its grassy top broken.
for (let y = SPIT + 3; y > SPIT - 40; y -= 6) {
  for (let x = -40; x < 620; x += rand(60, 110)) {
    const len = rand(80, 140);
    const end = Math.min(x + len, 610 - (SPIT - y) * 4);
    if (y < spitTop(x + len / 2) + 2 || end < x + 10) continue;
    const xx = x + len / 2 + 70 * noise(x / 60, y / 20);
    stroke({
      path: [
        [x, y + rand(-1.5, 1.5), 0.6],
        [end, y + rand(-1.5, 1.5), 0.2],
      ],
      brush: { type: 'soft', width: 14 },
      color: xx < 230 ? 'spit' : xx < 430 ? 'spitPale' : 'spitPoint',
      load: rand(0.7, 0.8),
      thinner: 0.2,
    });
  }
}
for (let x = -10; x < 560; x += rand(5, 11)) {
  const y = spitTop(x) + 4;
  stroke({
    path: [
      [x, y],
      [x + rand(-3, 3), y - rand(5, 14)],
    ],
    brush: { type: 'round', width: rand(2, 3.5) },
    color: x + rand(-60, 60) < 320 ? 'grass' : 'grassPale',
    load: rand(0.6, 0.75),
    end: 'taper',
  });
}

// The trunks and limbs, before the foliage, so the crowns bury the limbs' ends. Each bole
// is laid twice, the second stroke picking up the first rather than the fog behind it,
// and flares a little where it meets the bank.
for (const t of TREES) {
  const size = t.h / 570;
  const { fork } = t;
  const bole = [
    [t.x, t.foot + 2, 1],
    [t.x + t.lean * 0.12, t.foot - 0.05 * t.h, 0.92],
    [fork.x, fork.y, 0.82],
  ];
  // up from the foot, then down from the fork, so neither end is the one left pale, and
  // once more over the upper bole, where the bank of mist behind it is thickest
  stroke({ path: bole, brush: { type: 'soft', width: 24 * size }, color: 'trunk', load: 0.92 });
  stroke({
    path: bole.toReversed(),
    brush: { type: 'soft', width: 18 * size },
    color: 'trunk',
    load: 0.92,
  });
  for (const [a, b] of [
    [0, 1],
    [1, 0],
  ]) {
    const ends = [
      [fork.x, fork.y + 4, 0.85],
      [t.x + t.lean * 0.1, t.foot - 0.04 * t.h, 0.8],
    ];
    stroke({
      path: [ends[a], ends[b]],
      brush: { type: 'soft', width: 19 * size, reservoir: 2 },
      color: 'trunk',
      load: 1,
    });
  }
  stroke({
    path: [
      [t.x - 2, t.foot + 3, 1],
      [t.x, t.foot - 0.025 * t.h, 0.6],
    ],
    brush: { type: 'soft', width: 30 * size },
    color: 'trunk',
    load: 0.9,
  });
  // the limbs rise steeply out of the fork and arch outward in a vase, the outer two
  // throwing a branch wider still
  const rise = fork.y - (t.top + 0.62 * t.h);
  for (const [u, w] of [
    [-0.45, 14],
    [0.04, 12],
    [0.48, 13],
  ]) {
    const dx = t.cx - fork.x + (u + 0.12 * noise(t.k * 4.1, u * 3)) * t.spread;
    const lift = rise * (1 + 0.15 * noise(t.k * 2.3, u * 5));
    const limb = [
      [fork.x + u * 8 * size, fork.y + 4, 0.95],
      [fork.x + dx * 0.18, fork.y - lift * 0.4, 0.75],
      [fork.x + dx * 0.62, fork.y - lift * 0.82, 0.55],
      [fork.x + dx, fork.y - lift, 0.4],
    ];
    stroke({ path: limb, brush: { type: 'soft', width: w * size }, color: 'limb', load: 0.92 });
    if (Math.abs(u) < 0.3) continue;
    const [bx, by] = limb[1];
    stroke({
      path: [
        [bx, by, 0.8],
        [bx + dx * 0.55, by - lift * 0.3, 0.55],
        [bx + dx * 1.05, by - lift * 0.5, 0.35],
      ],
      brush: { type: 'soft', width: 9 * size },
      color: 'limb',
      load: 0.9,
      end: 'taper',
    });
  }
}

/**
 * One layer of a crown: strokes scattered evenly over every crown (a jittered grid of
 * `cell` px), each at its own slant, run out from its point both ways until it nears the
 * rim, so no stroke sticks out past the silhouette. `inset` keeps a layer inside the rim,
 * and `only` limits it to the darker steps.
 */
function layer({ cell, inset, width, len, only = 5 }) {
  for (let gy = 40; gy < 620; gy += cell) {
    for (let gx = -30; gx < 580; gx += cell) {
      const x = gx + rand(cell);
      const y = gy + rand(cell);
      const c = crownAt(x, y);
      if (c.depth < inset || c.step > only) continue;
      const a = rand(-0.45, 0.45) + 0.35 * noise(x / 90, y / 90);
      const ux = Math.cos(a);
      const uy = Math.sin(a);
      const reach = (dir) => {
        let s = 0;
        const want = rand(len[0], len[1]) / 2;
        while (s < want && crownAt(x + dir * ux * (s + 4), y + dir * uy * (s + 4)).depth > inset)
          s += 4;
        return s;
      };
      const s0 = reach(-1);
      const s1 = reach(1);
      if (s0 + s1 < 14) continue;
      const bow = rand(-4, 4);
      stroke({
        path: [
          [x - ux * s0, y - uy * s0, 0.42],
          [x - (ux * s0) / 3 - uy * bow, y - (uy * s0) / 3 + ux * bow, rand(0.65, 0.8)],
          [x + (ux * s1) / 3 - uy * bow, y + (uy * s1) / 3 + ux * bow, rand(0.65, 0.8)],
          [x + ux * s1, y + uy * s1, 0.42],
        ],
        brush: { type: 'soft', width },
        color: LADDER[c.step],
        load: rand(0.7, 0.8),
        thinner: 0.5,
      });
    }
  }
}

layer({ cell: 22, inset: 1, width: 32, len: [50, 110] });
layer({ cell: 18, inset: 9, width: 26, len: [40, 90] });
layer({ cell: 16, inset: 16, width: 20, len: [30, 70], only: 1 });

/**
 * The fog drifting through the tops: broad level strokes of the sky's own piles, thinned,
 * each crossing the rim of an upper crown from the fog side, so it lays sky into sky
 * until it reaches the wet foliage, then picks the foliage up and lays it down paler,
 * and never drags it out. The higher the rim, the more of them.
 */
for (let gy = 30; gy < 330; gy += 14) {
  for (let gx = -30; gx < 600; gx += 30) {
    const x = gx + rand(30);
    const y = gy + rand(14);
    if (Math.abs(crownAt(x, y).depth) > 10 || rand() > (330 - y) / 330) continue;
    // in from whichever side the fog is on, and only a little way into the foliage
    const dir = crownAt(x + 12, y).depth > crownAt(x - 12, y).depth ? 1 : -1;
    const out = rand(50, 110);
    const want = rand(30, 90);
    let inn = 6;
    while (inn < want && crownAt(x + dir * inn, y).depth < 18) inn += 6;
    const tilt = rand(-5, 5);
    stroke({
      path: [
        [x - dir * out, y - tilt, 0.1],
        [x - (dir * out) / 3, y - tilt / 3 + rand(-2, 2), rand(0.5, 0.6)],
        [x + (dir * inn) / 3, y + tilt / 3 + rand(-2, 2), rand(0.45, 0.55)],
        [x + dir * inn, y + tilt, 0.05],
      ],
      brush: { type: 'soft', width: rand(34, 56), reservoir: 3 },
      color: y + rand(-40, 40) < 330 ? 'sky4' : 'sky3',
      load: rand(0.5, 0.6),
      thinner: 0.5,
    });
  }
}

dry();

/**
 * Passage 5: the mud bar and the near water.
 *
 * A low bar of mud and rushes comes in from the right edge, the nearest land in the
 * picture, and ends in a point in the water where the heron will stand. It is laid in
 * level strokes of bank greyed less by the fog than the spit is, a paler step toward
 * its tip, with rushes standing out of it in fine strokes that pale step by step and are
 * lost toward the tip. Its reflection drops straight down below it. Close to us, a few
 * faint level wind-lines lie on the water.
 */

const W = canvas.width;
const BAR = 800; // the bar's waterline at its root on the right edge
const TIP = 880; // where the bar ends, in the water

/** The bar's waterline and its top at x: it rises a little toward the right edge. */
const barWater = (x) => BAR - (x - TIP) * 0.02 + 2 * noise(x / 60, 9.4);
const barTop = (x) =>
  barWater(x) - Math.min(1, (x - TIP) / 400) ** 0.6 * 26 - 3 * noise(x / 30, 2.2);

brush('mud', { type: 'soft', width: 12 });

// Faint wind-lines on the near water, lighter than the pond, before the bar goes over them.
for (let i = 0; i < 9; i++) {
  const y = 860 + i * 15 + rand(-5, 5);
  const x = rand(560, 1100);
  const len = rand(200, 420);
  stroke({
    path: [
      [x, y, 0.1],
      [x + len / 2, y + rand(-1, 1), 0.6],
      [x + len, y, 0.1],
    ],
    brush: { type: 'soft', width: 5 },
    color: 'windLine',
    load: rand(0.5, 0.6),
  });
}

// The bar itself, a paler step where it runs out into the water.
for (let y = BAR + 4; y > BAR - 40; y -= 5) {
  for (let x = TIP - 30; x < W + 40; x += rand(60, 120)) {
    const len = rand(90, 160);
    const start = Math.max(x, TIP + (BAR - y) * 9);
    if (y < barTop(start + len / 2) + 2) continue;
    stroke({
      path: [
        [start, y + rand(-1, 1), 0.3],
        [start + len / 2, y + rand(-1.5, 1.5), 0.8],
        [start + len, y + rand(-1, 1), 0.6],
      ],
      brush: 'mud',
      color: start + 80 * noise(start / 50, y / 10) < 1080 ? 'barTip' : 'bar',
      load: rand(0.8, 0.9),
    });
  }
}
// its wet lip, a thin dark line where mud meets water
stroke({
  path: [
    [TIP - 6, barWater(TIP) + 1, 0.2],
    [1100, barWater(1100) + 2, 0.6],
    [W + 20, barWater(W) + 2, 0.7],
  ],
  brush: { type: 'soft', width: 4 },
  color: 'barLip',
  load: 0.8,
});
// rushes: fine strokes rising out of the bar, thick toward the edge, lost toward the tip
for (let x = TIP + 30; x < W + 10; x += rand(3, 8)) {
  const rise = Math.min(1, (x - TIP) / 500);
  if (rand() > 0.3 + rise * 0.6) continue;
  const foot = barTop(x) + 3;
  const tall = rand(10, 46) * (0.3 + rise);
  const zone = x + rand(-60, 60);
  stroke({
    path: [
      [x, foot, 0.8],
      [x + rand(-2, 4), foot - tall * 0.6, 0.5],
      [x + rand(-1, 8), foot - tall, 0.1],
    ],
    brush: { type: 'round', width: rand(1.5, 3) },
    color: zone < 1060 ? 'rushLost' : zone < 1240 ? 'rushPale' : 'rush',
    load: rand(0.7, 0.8),
    end: 'flick',
  });
}

// The reflection: short uprights of mud and rush below the bar, broken level.
for (let x = TIP; x < W + 10; x += rand(6, 11)) {
  const y0 = barWater(x) + 3;
  const len = (barWater(x) - barTop(x)) * rand(0.7, 1.2) + rand(4, 20);
  stroke({
    path: [
      [x, y0, 0.8],
      [x + rand(-1, 1), y0 + len, 0.1],
    ],
    brush: { type: 'soft', width: rand(6, 10) },
    color: 'barMirror',
    load: rand(0.45, 0.55),
  });
}

dry();

/**
 * Passage 6: the accents, last and crispest.
 *
 * Everything so far has been soft and close in value; two notes break that, where the
 * eye should land. A thin line of silver light lies across the water under the glow,
 * a wind-lane on the still pond, drawn with a fine round brush in fuller paint. And at
 * the point of the mud bar a heron stands in the shallows, the darkest thing in the
 * picture, its edges crisp: body, folded neck, dagger bill, legs going into the water,
 * and its broken reflection. Two faint rings of ripple spread from its legs.
 */

const GLOW = { x: 1040, y: 300 };
const HERON = { x: 902, foot: 812 }; // where its legs meet the water

// The wind-lane: a long, thin line of light, brightest under the glow, fading at both
// ends, with a fainter second line below it.
for (const [y, len, w, strength] of [
  [592, 520, 2.6, 1],
  [608, 300, 1.8, 0.6],
]) {
  stroke({
    path: [
      [GLOW.x - len, y + 2, 0.05],
      [GLOW.x - len * 0.4, y + 0.5, 0.5 * strength],
      [GLOW.x + 20, y, 0.9 * strength],
      [GLOW.x + len * 0.5, y - 0.5, 0.5 * strength],
      [GLOW.x + len, y - 1, 0.05],
    ],
    brush: { type: 'round', width: w },
    color: 'silver',
    load: 0.9,
  });
}

// The heron, facing left into the fog. s scales its drawing (its height is about 70 px).
const s = 1.25;
const at0 = (dx, dy) => [HERON.x + dx * s, HERON.foot - dy * s];
const heron = { color: 'heron', load: 0.9 };
// body: a tilted teardrop, the back higher than the breast
for (let k = 0; k < 4; k++)
  stroke({
    path: [at0(16 + k, 42 - k * 2), at0(0, 47 - k * 3), at0(-14, 52 - k * 3)],
    brush: { type: 'soft', width: 10 - k * 1.5 },
    pressure: 0.9,
    end: 'taper',
    ...heron,
  });
// the drooping tail feathers and the folded wing's lower edge
stroke({
  path: [at0(-2, 40), at0(12, 36), at0(22, 33)],
  brush: { type: 'round', width: 4 },
  end: 'taper',
  ...heron,
});
// the neck, folded back in an S, and the head
stroke({
  path: [at0(-13, 52), at0(-17, 60), at0(-12, 66), at0(-15, 72)],
  brush: { type: 'round', width: 4.5 },
  pressure: 0.85,
  ...heron,
});
stroke({ path: [at0(-15, 73)], brush: { type: 'round', width: 6 }, ...heron });
// the bill, a dagger pointing left
stroke({
  path: [at0(-17, 73.5), at0(-24, 72.5), at0(-31, 71.5)],
  brush: { type: 'round', width: 2.2 },
  pressure: 0.8,
  end: 'taper',
  ...heron,
});
// a pale wash of the fog light along its back, the one soft edge on it
stroke({
  path: [at0(12, 47), at0(0, 52), at0(-10, 55)],
  brush: { type: 'round', width: 2 },
  color: 'heronLit',
  load: 0.6,
  end: 'taper',
});
// legs, into the water
for (const dx of [-2, 3])
  stroke({
    path: [at0(dx, 38), at0(dx + 0.5, 0)],
    brush: { type: 'round', width: 1.6 },
    color: 'heron',
    load: 0.9,
    end: 'stop',
  });

// Its reflection: the legs and body hanging upside down, paler, broken by the water.
for (const dx of [-2, 3]) {
  for (let d = 3; d < 38; d += rand(6, 10))
    stroke({
      path: [
        [HERON.x + dx * s, HERON.foot + d * s],
        [HERON.x + (dx + 0.5) * s, HERON.foot + (d + rand(3, 5)) * s],
      ],
      brush: { type: 'round', width: 1.4 },
      color: 'heronMirror',
      load: 0.7,
    });
}
for (let dx = -12; dx <= 16; dx += 4) {
  const d0 = 40 + Math.abs(dx - 2) * 0.35 + rand(-2, 2);
  stroke({
    path: [
      [HERON.x + dx * s, HERON.foot + d0 * s, 0.7],
      [HERON.x + dx * s + rand(-1, 1), HERON.foot + (d0 + rand(6, 14)) * s, 0.1],
    ],
    brush: { type: 'soft', width: 5 },
    color: 'heronMirrorPale',
    load: 0.7,
  });
}
// rings of ripple spreading from its legs
for (const [r, w] of [
  [16, 1.2],
  [30, 0.9],
]) {
  const ring = [];
  for (let a = 0; a <= Math.PI * 2 + 0.01; a += 0.25)
    ring.push([HERON.x + Math.cos(a) * r * s, HERON.foot + 2 + Math.sin(a) * r * 0.16 * s]);
  stroke({
    path: ring,
    brush: { type: 'round', width: w },
    color: 'ripple',
    load: 0.55,
    pressure: 0.5,
  });
}
